import urllib.error
import urllib.request
from pathlib import Path

from src.mythosmini.config import LEADERBOARD_URL
from src.mythosmini.leaderboard.entries import LeaderboardEntry, parse_leaderboard_html

FETCH_TIMEOUT_SECONDS = 30.0


def download_leaderboard_html(url: str = LEADERBOARD_URL) -> str:
    request = urllib.request.Request(url, headers={"User-Agent": "mythosmini-trainer"})
    with urllib.request.urlopen(request, timeout=FETCH_TIMEOUT_SECONDS) as response:
        body: bytes = response.read()
    return body.decode("utf-8")


def fetch_leaderboard(cache_path: Path, url: str = LEADERBOARD_URL) -> list[LeaderboardEntry]:
    try:
        html = download_leaderboard_html(url)
    except (urllib.error.URLError, TimeoutError, OSError) as error:
        if cache_path.is_file():
            print(f"leaderboard fetch failed ({error}); using cached copy at {cache_path}")
            return parse_leaderboard_html(cache_path.read_text(encoding="utf-8"))
        print(f"leaderboard fetch failed ({error}); placements will be unavailable")
        return []
    cache_path.parent.mkdir(parents=True, exist_ok=True)
    cache_path.write_text(html, encoding="utf-8")
    return parse_leaderboard_html(html)
